import { useCallback, useEffect, useRef, useState } from 'react';
import {
  createRecognizer,
  isSpeechRecognitionSupported,
} from '../services/voiceService';

export const VOICE_ERROR = {
  UNSUPPORTED: 'unsupported',
  PERMISSION_DENIED: 'permission-denied',
  NO_SPEECH: 'no-speech',
  UNKNOWN: 'unknown',
};

// continuous/autoRestart are additive, opt-in params. Default behaviour
// (continuous: false, autoRestart: false) is unchanged from the original
// push-to-talk hook — existing callers (ChatInput) are unaffected.
export function useVoiceInput({
  onResult,
  lang = 'en-AU',
  continuous = false,
  autoRestart = false,
} = {}) {
  const supported = isSpeechRecognitionSupported();
  const recognizerRef = useRef(null);

  // Tracks caller *intent* separately from the recognizer's own lifecycle,
  // so autoRestart only fires when the browser ended the session on its
  // own (e.g. silence timeout) — never after an explicit stop().
  const shouldListenRef = useRef(false);

  // Holds the latest beginRecognition function so attachRecognizer's onend
  // handler can call it without needing it in its own dependency array —
  // avoids a declaration-order/exhaustive-deps issue entirely.
  const beginRecognitionRef = useRef(() => {});

  const [listening, setListening] = useState(false);
  const [interimTranscript, setInterimTranscript] = useState('');
  const [error, setError] = useState(null);

  const attachRecognizer = useCallback(
    (recognizer) => {
      recognizer.onstart = () => {
        setListening(true);
      };

      recognizer.onerror = (event) => {
        setListening(false);

        // In autoRestart mode, "no-speech" just means the user hasn't
        // started talking yet — that's normal in a hands-free session,
        // not a failure state worth surfacing to the UI.
        if (event.error === 'no-speech' && autoRestart && shouldListenRef.current) {
          return;
        }

        if (
          event.error === 'not-allowed' ||
          event.error === 'service-not-allowed'
        ) {
          setError(VOICE_ERROR.PERMISSION_DENIED);
          shouldListenRef.current = false;
        } else if (event.error === 'no-speech') {
          setError(VOICE_ERROR.NO_SPEECH);
        } else if (event.error === 'aborted') {
          // Fired by our own stop()/barge-in calls — expected, not an error.
        } else {
          setError(VOICE_ERROR.UNKNOWN);
        }
      };

      recognizer.onresult = (event) => {
        let finalTranscript = '';
        let interim = '';

        for (
          let i = event.resultIndex;
          i < event.results.length;
          i += 1
        ) {
          const transcript = event.results[i][0].transcript;

          if (event.results[i].isFinal) {
            finalTranscript += transcript;
          } else {
            interim += transcript;
          }
        }

        setInterimTranscript(interim);

        if (finalTranscript.trim()) {
          onResult?.(finalTranscript.trim());
        }
      };

      recognizer.onend = () => {
        setListening(false);
        setInterimTranscript('');

        // Browser ended the session by itself (timeout, continuous
        // session cap, etc). If the caller still wants to be listening,
        // pick it back up. A short delay avoids a tight error/restart
        // loop on browsers that end sessions immediately.
        if (autoRestart && shouldListenRef.current) {
          setTimeout(() => {
            if (shouldListenRef.current) beginRecognitionRef.current();
          }, 250);
        }
      };

      recognizerRef.current = recognizer;
    },
    [onResult, autoRestart]
  );

  const beginRecognition = useCallback(() => {
    if (!supported) {
      setError(VOICE_ERROR.UNSUPPORTED);
      return;
    }

    const recognizer = createRecognizer({
      lang,
      interimResults: true,
      continuous,
    });

    if (!recognizer) {
      setError(VOICE_ERROR.UNSUPPORTED);
      return;
    }

    attachRecognizer(recognizer);

    try {
      recognizer.start();
    } catch {
      setError(VOICE_ERROR.UNKNOWN);
    }
  }, [supported, lang, continuous, attachRecognizer]);

  // Keep the ref in sync with the latest beginRecognition on every render
  // where it changes, so the onend handler above always calls the current
  // version (correct lang/continuous closed over) without being a dep.
  useEffect(() => {
    beginRecognitionRef.current = beginRecognition;
  }, [beginRecognition]);

  const start = useCallback(() => {
    if (!supported) {
      setError(VOICE_ERROR.UNSUPPORTED);
      return;
    }

    setError(null);
    setInterimTranscript('');
    shouldListenRef.current = true;
    beginRecognition();
  }, [supported, beginRecognition]);

  const stop = useCallback(() => {
    shouldListenRef.current = false;
    recognizerRef.current?.stop();
  }, []);

  useEffect(() => {
    return () => {
      shouldListenRef.current = false;
      recognizerRef.current?.stop();
    };
  }, []);

  const clearError = useCallback(() => {
    setError(null);
  }, []);

  return {
    supported,
    listening,
    interimTranscript,
    error,
    start,
    stop,
    clearError,
  };
}

export default useVoiceInput;
